function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof MARATHA_INFO&&(n.innerHTML=MARATHA_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderCoins(){const n=document.getElementById("coins-grid");n&&"undefined"!=typeof COIN_TYPES&&(n.innerHTML=COIN_TYPES.map(n=>`\n        <div class="coin-card" id="coin-${n.id}">\n            <div class="coin-header">\n                <h3>🪙 ${n.name}</h3>\n                <span class="coin-ruler">${n.ruler}</span>\n            </div>\n            <div class="coin-details">\n                <p><strong>Metal & Weight:</strong> ${n.metal}</p>\n                <p><strong>Denomination:</strong> ${n.denomination}</p>\n                <p><strong>Script:</strong> ${n.script}</p>\n                <p><strong>Obverse Legend:</strong> <em>"${n.obverseText}"</em></p>\n                <p><strong>Reverse Legend:</strong> <em>"${n.reverseText}"</em></p>\n                <p><strong>Circulation:</strong> ${n.circulation}</p>\n                <p class="coin-history"><strong>Historical Context:</strong> ${n.history}</p>\n            </div>\n        </div>\n    `).join(""))}function renderScriptDecoder(){const n=document.getElementById("script-grid");n&&"undefined"!=typeof SCRIPT_DECODER_ITEMS&&(n.innerHTML=SCRIPT_DECODER_ITEMS.map(n=>`\n        <div class="script-card">\n            <div class="script-char">${n.character}</div>\n            <div class="script-type">${n.scriptType}</div>\n            <p>${n.meaning}</p>\n        </div>\n    `).join(""))}function renderSymbols(){const n=document.getElementById("symbols-grid");n&&"undefined"!=typeof SYMBOL_HOTSPOTS&&(n.innerHTML=SYMBOL_HOTSPOTS.map(n=>`\n        <div class="symbol-card">\n            <h3>🔱 ${n.symbol}</h3>\n            <p><strong>Meaning:</strong> ${n.meaning}</p>\n            <p class="symbol-loc"><strong>Location:</strong> ${n.location}</p>\n        </div>\n    `).join(""))}function renderTerritories(){const n=document.getElementById("territory-grid");n&&"undefined"!=typeof TERRITORY_MAP_REGIONS&&(n.innerHTML=TERRITORY_MAP_REGIONS.map(n=>`\n        <div class="territory-card">\n            <h3>🗺️ ${n.region}</h3>\n            <p><strong>Capital/Seat:</strong> ${n.capital}</p>\n            <p><strong>Primary Coinage:</strong> ${n.mainCoin}</p>\n        </div>\n    `).join(""))}function renderTimeline(){const n=document.getElementById("timeline-container");n&&"undefined"!=typeof TIMELINE_EVENTS&&(n.innerHTML=TIMELINE_EVENTS.map(n=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${n.year}</div>\n            <div class="timeline-content">\n                <h3>${n.title}</h3>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderCoins(),renderScriptDecoder(),renderSymbols(),renderTerritories(),renderTimeline(),renderReferences(),initThemeToggle()});